for case in range(int(input())):
	(n, m) = map(int, input().split())
	a = [list(map(int, input().split())) for _ in range(n)]
	if (n + m - 1) % 2:
		print('NO')
		continue
	dp = [0] * (m + 1)
	for i in range(n):
		dp[0] = int(not i)
		for j in range(m):
			dp[j + 1] = (dp[j] | dp[j + 1]) << (a[i][j] == -1)
	if dp[-1] & 1 << (n + m - 1) // 2:
		print('YES')
	else:
		print('NO')
